simpleTextureVertexShader:
attribute vec4 vPosition;
attribute vec2 texCoord0;
varying vec2 texCoord;
void main() {
    gl_Position = vPosition;
    texCoord = texCoord0;
}

simpleCubeMapTextureFragmentShader:
precision mediump float;
uniform samplerCube tex;
uniform highp int face;
varying vec2 texCoord;
void main() {
    vec2 texC2 = (texCoord * 2.) - 1.;
    vec3 texCube = vec3(0., 0., 0.);
    if (face == 34069) {
        texCube = vec3(1., -texC2.y, -texC2.x);
    } else if (face == 34070) {
        texCube = vec3(-1., -texC2.y, texC2.x);
    } else if (face == 34071) {
        texCube = vec3(texC2.x, 1., texC2.y);
    } else if (face == 34072) {
        texCube = vec3(texC2.x, -1., -texC2.y);
    } else if (face == 34073) {
        texCube = vec3(texC2.x, -texC2.y, 1.);
    } else if (face == 34074) {
        texCube = vec3(-texC2.x, -texC2.y, -1.);
    }
    gl_FragData[0] = textureCube(tex, texCube);
}

fragDataReadFragmentShader:
precision mediump float;
varying vec2 texCoord;
void main() {
    gl_FragData[0] = vec4(1., 0., 0., 1.);
    if (texCoord.x < 0.5) {
        gl_FragData[0].g = gl_FragData[0].r;
        return;
    }
    gl_FragData[0] = gl_FragData[0].bgra;
}
